import json
from pathlib import Path

ROOT = Path('/root')

DISPATCH_MODELS = {
    '6_day': {'dispatches_per_year': 60, 'days_per_dispatch': 6},
    '12_day': {'dispatches_per_year': 30, 'days_per_dispatch': 12},
}
DECISION_THRESHOLD_USD = 11000


def read_csv(name):
    with open(ROOT / name, newline='') as f:
        return list(csv.DictReader(f))


def is_blank(value):
    return value is None or str(value).strip() == ''


def to_float(value):
    return float(str(value).strip())


def to_int(value):
    return int(float(str(value).strip()))


def load_campaigns(path):
    with open(path) as f:
        data = json.load(f)

    if isinstance(data, list):
        return data

    campaigns = []
    if isinstance(data, dict):
        if isinstance(data.get('campaigns'), list):
            campaigns.extend(data['campaigns'])
        if isinstance(data.get('regions'), list):
            for region in data['regions']:
                if isinstance(region, dict) and isinstance(region.get('campaigns'), list):
                    campaigns.extend(region['campaigns'])
    return campaigns


def select_billing(campaign, billing_rows):
    aliases = campaign.get('alias_labels') or []
    if not isinstance(aliases, list):
        aliases = [aliases]
    labels = {campaign.get('campaign_name'), *aliases}

    matches = [
        row for row in billing_rows
        if row.get('status') == 'active' and row.get('campaign_label') in labels
    ]
    if not matches:
        raise ValueError(f"No active billing row found for {campaign['campaign_id']}")
    return max(matches, key=lambda row: row.get('cycle_tag', ''))


def build_overrides(rows):
    selected = {}
    for row in rows:
        if row.get('state') != 'approved':
            continue
        if is_blank(row.get('revision')) or is_blank(row.get('active_clinics')):
            continue
        cid = row['campaign_id']
        revision = to_int(row['revision'])
        active_clinics = to_int(row['active_clinics'])
        if cid not in selected or revision > selected[cid]['revision']:
            selected[cid] = {'revision': revision, 'active_clinics': active_clinics}
    return selected


def model_financials(campaign, payment, active_clinics, crate_cost, days_per_dispatch, dispatches_per_year):
    drug_cost_per_1000 = to_float(campaign['drug_cost_per_1000_doses_usd'])
    doses_per_day = to_float(campaign['doses_per_day'])

    annual_revenue = payment * active_clinics * dispatches_per_year
    annual_drug_cost = (
        drug_cost_per_1000
        * active_clinics
        * doses_per_day
        * days_per_dispatch
        * dispatches_per_year
        / 1000
    )
    # crate_cost_usd is a cost per crate/dispatch tier in the source table, so annualize by dispatch count.
    annual_crate_cost = crate_cost * dispatches_per_year
    annual_margin = annual_revenue - annual_drug_cost - annual_crate_cost

    return {
        'dispatches_per_year': dispatches_per_year,
        'days_per_dispatch': days_per_dispatch,
        'annual_revenue': round(annual_revenue, 2),
        'annual_drug_cost': round(annual_drug_cost, 2),
        'annual_crate_cost': round(annual_crate_cost, 2),
        'annual_margin': round(annual_margin, 2),
    }


def main():
    campaigns = load_campaigns(ROOT / 'campaign_manifest.json')
    crate_rows = read_csv('crate_cost.csv')
    billing_rows = read_csv('billing.csv')
    override_rows = read_csv('location_overrides.csv')
    suspension_rows = read_csv('suspensions.csv')

    crate_cost_by_tier = {row['crate_tier']: to_float(row['crate_cost_usd']) for row in crate_rows}
    held_campaign_ids = {
        row['campaign_id'] for row in suspension_rows
        if row.get('suspension_status') == 'hold'
    }
    overrides = build_overrides(override_rows)

    retained = [
        campaign for campaign in campaigns
        if campaign.get('analysis_flag') == 'review'
        and campaign.get('campaign_id') not in held_campaign_ids
    ]

    output_campaigns = []
    for campaign in retained:
        cid = campaign['campaign_id']
        billing = select_billing(campaign, billing_rows)
        payment = to_float(billing['payment_per_dispatch_per_clinic_usd'])
        active_clinics = overrides.get(cid, {}).get('active_clinics', to_int(campaign['default_active_clinics']))
        crate_cost = crate_cost_by_tier[campaign['crate_tier']]

        six_day = model_financials(
            campaign,
            payment,
            active_clinics,
            crate_cost,
            DISPATCH_MODELS['6_day']['days_per_dispatch'],
            DISPATCH_MODELS['6_day']['dispatches_per_year'],
        )
        twelve_day = model_financials(
            campaign,
            payment,
            active_clinics,
            crate_cost,
            DISPATCH_MODELS['12_day']['days_per_dispatch'],
            DISPATCH_MODELS['12_day']['dispatches_per_year'],
        )
        difference = round(twelve_day['annual_margin'] - six_day['annual_margin'], 2)

        output_campaigns.append({
            'campaign_id': cid,
            'campaign_name': campaign['campaign_name'],
            'active_clinics': active_clinics,
            'payment_per_dispatch_per_clinic_usd': round(payment, 2),
            'crate_tier': campaign['crate_tier'],
            'crate_cost_usd': round(crate_cost, 2),
            'drug_cost_per_1000_doses_usd': round(to_float(campaign['drug_cost_per_1000_doses_usd']), 2),
            'doses_per_day': to_float(campaign['doses_per_day']),
            'billing_cycle_tag': billing['cycle_tag'],
            'six_day': six_day,
            'twelve_day': twelve_day,
            'difference': difference,
        })

    output_campaigns.sort(key=lambda row: row['campaign_id'])

    total_6_day_margin = round(sum(row['six_day']['annual_margin'] for row in output_campaigns), 2)
    total_12_day_margin = round(sum(row['twelve_day']['annual_margin'] for row in output_campaigns), 2)
    total_difference = round(total_12_day_margin - total_6_day_margin, 2)
    absolute_total_margin_difference = round(abs(total_difference), 2)
    decision = 'move_to_12_day' if abs(total_difference) < DECISION_THRESHOLD_USD else 'keep_6_day'

    analysis = {
        'assumptions': {
            'six_day_dispatches_per_year': 60,
            'six_day_days_per_dispatch': 6,
            'twelve_day_dispatches_per_year': 30,
            'twelve_day_days_per_dispatch': 12,
            'decision_threshold_usd': DECISION_THRESHOLD_USD,
            'crate_cost_interpretation': 'crate_cost_usd is per dispatch and annual_crate_cost = crate_cost_usd * dispatches_per_year',
        },
        'campaigns': output_campaigns,
        'totals': {
            'total_6_day_margin': total_6_day_margin,
            'total_12_day_margin': total_12_day_margin,
            'total_difference': total_difference,
            'absolute_total_margin_difference': absolute_total_margin_difference,
        },
        'recommendation': {
            'decision': decision,
            'justification': (
                f"Absolute total margin difference is ${absolute_total_margin_difference:.2f}, "
                f"which is {'below' if absolute_total_margin_difference < DECISION_THRESHOLD_USD else 'at or above'} "
                f"the ${DECISION_THRESHOLD_USD:.2f} threshold."
            ),
        },
    }

    with open(ROOT / 'vaxcrate_analysis.json', 'w') as f:
        json.dump(analysis, f, indent=2)
        f.write('\n')

    summary_lines = [
        f"Total 6-day margin (USD): ${total_6_day_margin:.2f}",
        f"Total 12-day margin (USD): ${total_12_day_margin:.2f}",
        f"Absolute difference (USD): ${absolute_total_margin_difference:.2f}",
        f"Final decision: {decision}",
    ]
    with open(ROOT / 'vaxcrate_summary.md', 'w') as f:
        f.write('\n'.join(summary_lines) + '\n')


if __name__ == '__main__':
    main()
